CREATE TABLE IF NOT EXISTS reference_transcripts(id TEXT PRIMARY KEY,reference_id TEXT NOT NULL REFERENCES "references"(id),origin TEXT NOT NULL,rights_note TEXT NOT NULL,language TEXT NOT NULL,content TEXT NOT NULL,sha256 TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(reference_id,sha256));
CREATE TABLE IF NOT EXISTS reference_analyses(id TEXT PRIMARY KEY,reference_id TEXT NOT NULL REFERENCES "references"(id),version INTEGER NOT NULL,source_hash TEXT NOT NULL,source_kind TEXT NOT NULL,provider TEXT NOT NULL,status TEXT NOT NULL,packaging_json TEXT NOT NULL,narrative_json TEXT NOT NULL,limitations_json TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(reference_id,version));
CREATE INDEX IF NOT EXISTS ix_reference_analyses_ref ON reference_analyses(reference_id,version DESC);
